use verus::prelude::*;

verus! {

    /// Iteratively reverses a non‐empty vector of chars.
    /// 
    /// Requirements:
    /// - `a.len() > 0`
    ///
    /// Guarantees:
    /// - The result has the same length as `a`.
    /// - For every index `k` in the result, `res[k] == a[a.len() - 1 - k]`.
    fn reverse(a: &Vec<char>) -> Vec<char> {
        // Precondition: input is non‐empty
        requires(a.len() > 0);
        // Postcondition: same length, and reversed contents
        ensures(|res: &Vec<char>|
            res.len() == a.len() &&
            forall(|k: usize| k < a.len() ==>
                res[k] == a[a.len() - 1 - k]
            )
        );

        let mut res: Vec<char> = Vec::new();
        // Reserve space so that pushing is safe
        res.reserve(a.len());

        // We'll iterate with a decreasing index `i`, initially at a.len()
        // At each iteration we decrement `i` and push a[i].
        let mut i: usize = a.len();
        while i > 0 {
            // Loop invariants:
            // 1) 0 <= i <= a.len()
            invariant(i <= a.len());
            // 2) We've pushed exactly (a.len() - i) elements so far
            invariant(res.len() == a.len() - i);
            // 3) Those pushed elements satisfy the reverse property
            invariant(
                forall(|j: usize| j < res.len() ==>
                    res[j] == a[a.len() - 1 - j]
                )
            );
            // Ensure termination since `i` strictly decreases
            decreases(i);

            // Body: decrement `i` then push a[i]
            i -= 1;
            res.push(a[i]);
        }

        // Now i == 0, res.len() == a.len(), and res is the full reverse of a
        res
    }

}